inline std::string uri_decode(const std::string& s){std::string o;for(size_t i=0;i<s.size();++i){if(s[i]=='%'&&i+2<s.size()&&hex_digit(s[i+1])>=0&&hex_digit(s[i+2])>=0){o+=char(hex_digit(s[i+1])*16+hex_digit(s[i+2]));i+=2;}else o+=s[i];}return o;}
