inline std::string from_bytes(const Bytes& b){return std::string(b.begin(),b.end());}
inline Bytes to_bytes(const std::string& s){return Bytes(s.begin(),s.end());}
using Options=std::map<std::string,std::string>;
inline Options uri_query(const std::string& s){Options q;std::istringstream in(s);std::string item;while(std::getline(in,item,'&')){auto eq=item.find('=');if(eq==std::string::npos)continue;q.emplace(lower(uri_decode(item.substr(0,eq))),uri_decode(item.substr(eq+1)));}return q;}
inline std::string option(const Options& q,std::initializer_list<const char*> keys,const std::string& d=""){for(auto k:keys){auto i=q.find(k);if(i!=q.end())return i->second;}return d;}
inline bool present(const Options& q,std::initializer_list<const char*> keys){for(auto k:keys)if(q.count(k))return true;return false;}
inline bool true_value(std::string v){v=lower(v);return v=="1"||v=="true"||v=="yes"||v=="on";}
inline std::string transport_name(std::string v){auto k=lower(trim(v));if(k=="mkcp"||k=="kcp")return "kcp";if(k.empty()||k=="tcp"||k=="raw")return "raw";if(k=="http"||k=="h2"||k=="http2")return "http";if(k=="ws"||k=="websocket")return "websocket";if(k=="gun"||k=="grpc")return "grpc";if(k=="splithttp"||k=="xhttp")return "xhttp";if(k=="http-upgrade"||k=="httpupgrade")return "httpupgrade";return trim(v);}
inline std::string security_name(std::string v){auto k=lower(trim(v));if(k=="1"||k=="true"||k=="on"||k=="tls")return "tls";if(k.empty()||k=="0"||k=="false"||k=="off"||k=="none")return "none";if(k=="reality")return "reality";if(k=="xtls")return "xtls";return trim(v);}
inline Options raw_uri_query(const std::string& s){Options q;std::istringstream in(s);std::string item;while(std::getline(in,item,'&')){auto eq=item.find('=');if(eq!=std::string::npos)q.emplace(lower(uri_decode(item.substr(0,eq))),item.substr(eq+1));}return q;}
inline std::string form_field(std::string raw){std::replace(raw.begin(),raw.end(),'+',' ');return uri_decode(raw);}
inline std::string enum_field(const Options& raw,const Options& decoded,std::initializer_list<const char*> keys,bool transport){auto value=option(decoded,keys);auto source=option(raw,keys);if(source.find('+')==std::string::npos)return value;auto candidate=form_field(source);auto canonical=transport?transport_name(candidate):security_name(candidate);const std::set<std::string> networks{"raw","websocket","httpupgrade","grpc","xhttp","http","kcp","quic","domainsocket","ds","meek","hysteria","hysteria2"};const std::set<std::string> security{"none","tls","reality","xtls"};return (transport?networks:security).count(canonical)?candidate:value;}
inline Json optional_json(const std::string& decoded,const std::string& raw){if(trim(decoded).empty())return Json();try{return json_parse(decoded);}catch(...){if(raw.find('+')!=std::string::npos){try{auto j=json_parse(form_field(raw));if(j.kind==Json::Object)return j;}catch(...){}}return Json(decoded);}}
