inline Bytes digest(const std::string& algorithm,const Bytes& data);
inline std::array<uint8_t,16> uuid_bytes(std::string s){std::array<uint8_t,16> b{};if(!s.empty()&&s.size()<=30){Bytes name(16);auto text=to_bytes(s);name.insert(name.end(),text.begin(),text.end());auto hash=digest("sha1",name);std::copy_n(hash.begin(),16,b.begin());b[6]=uint8_t((b[6]&15)|0x50);b[8]=uint8_t((b[8]&63)|0x80);return b;}s.erase(std::remove(s.begin(),s.end(),'-'),s.end());if(s.size()!=32)throw std::runtime_error("PARSE_INVALID: UUID must have 16 bytes");for(size_t i=0;i<16;++i){int a=hex_digit(s[2*i]),d=hex_digit(s[2*i+1]);if(a<0||d<0)throw std::runtime_error("PARSE_INVALID: invalid UUID");b[i]=uint8_t(a*16+d);}return b;}
inline void endpoint(Config& c,std::string s){auto slash=s.find('/');if(slash!=std::string::npos)s.resize(slash);std::string p;
    if(!s.empty()&&s[0]=='['){auto close=s.find(']');if(close==std::string::npos||close+1>=s.size()||s[close+1]!=':')throw std::runtime_error("PARSE_INVALID: invalid IPv6 endpoint");c.server=s.substr(1,close-1);p=s.substr(close+2);}else{auto colon=s.rfind(':');if(colon==std::string::npos||colon!=s.find(':'))throw std::runtime_error("PARSE_INVALID: endpoint requires host and port");c.server=s.substr(0,colon);p=s.substr(colon+1);}check_host(c.server);c.port=uint16_t(number(p,1,65535));}
inline Options sip003_options(const std::string& text){Options out;std::string item;bool escaped=false;auto add=[&]{auto equal=item.find('=');auto name=lower(trim(item.substr(0,equal)));if(!name.empty()&&!out.emplace(name,equal==std::string::npos?"":item.substr(equal+1)).second)throw std::runtime_error("PARSE_INVALID: duplicate plugin option");item.clear();};for(char ch:text){if(escaped){item+=ch;escaped=false;}else if(ch=='\\')escaped=true;else if(ch==';')add();else item+=ch;}if(escaped)throw std::runtime_error("PARSE_INVALID: plugin escape");add();return out;}
inline void parse_ss_plugin(Config& c){if(c.protocol!="ss")return;auto value=option(c.original_options,{"plugin"});if(value.empty()||std::set<std::string>{"none","0","false","off"}.count(lower(trim(value))))return;if(lower(value).find("v2ray-plugin%3b")==0){auto candidate=uri_decode(value);auto split=candidate.find(';');auto opts=sip003_options(candidate.substr(split+1));const std::set<std::string> allowed{"mode","host","path","tls","mux","sni","skip-cert-verify"};bool valid=true;for(const auto& p:opts)valid=valid&&allowed.count(p.first);if(opts.count("mode"))valid=valid&&opts.at("mode")=="websocket";if(opts.count("tls"))valid=valid&&opts.at("tls").empty();if(opts.count("skip-cert-verify"))valid=valid&&std::set<std::string>{"1","0","true","false"}.count(opts.at("skip-cert-verify"));if(opts.count("mux")){try{(void)number(opts.at("mux"),0,1024);}catch(...){valid=false;}}if(valid)value=candidate;}
    auto end=value.find(';');c.ss_plugin=lower(trim(value.substr(0,end)));for(unsigned char ch:c.ss_plugin)if(!((ch>='a'&&ch<='z')||(ch>='0'&&ch<='9')||ch=='-'||ch=='_'))throw std::runtime_error("PARSE_INVALID: plugin name");if(std::set<std::string>{"none","0","false","off"}.count(c.ss_plugin)){c.ss_plugin.clear();return;}if(c.ss_plugin!="v2ray-plugin")return;auto opts=sip003_options(end==std::string::npos?"":value.substr(end+1));if(true_value(option(opts,{"skip-cert-verify"})))c.legacy_insecure_requested=true;c.ss_plugin_mode=lower(option(opts,{"mode"},"websocket"));if(c.ss_plugin_mode!="websocket")return;c.transport="websocket";c.path=option(opts,{"path"},"/");c.host_header=option(opts,{"host"},"cloudfront.com");check_host(c.host_header);if(opts.count("tls")){c.security="tls";c.tls_name=c.host_header;c.explicit_sni=true;}auto mux=option(opts,{"mux"},"1");try{c.ss_plugin_mux=number(mux,0,1024)!=0;}catch(...){throw std::runtime_error("PARSE_INVALID: plugin mux");}}
